<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Core\TenantFeatures;
use EventMenu\Services\ConfiguredOrderService;
use EventMenu\Services\PublicMenuService;
use EventMenu\Services\TenantBrandService;

$pdo=Database::connection();
$slug=trim((string)($_GET['evento']??''));
$tenantSlug=trim((string)($_GET['empresa']??''));
if($slug===''){http_response_code(404);exit('Evento não encontrado.');}
if($tenantSlug!==''){
    $s=$pdo->prepare('SELECT e.*,t.name tenant_name,t.slug tenant_slug,t.status tenant_status FROM events e JOIN tenants t ON t.id=e.tenant_id WHERE t.slug=? AND e.slug=? AND e.status="published" AND t.status="active" LIMIT 1');
    $s->execute([$tenantSlug,$slug]);$event=$s->fetch();
}else{
    $s=$pdo->prepare('SELECT e.*,t.name tenant_name,t.slug tenant_slug,t.status tenant_status FROM events e JOIN tenants t ON t.id=e.tenant_id WHERE e.slug=? AND e.status="published" AND t.status="active" ORDER BY e.id LIMIT 2');
    $s->execute([$slug]);$matches=$s->fetchAll();
    if(count($matches)!==1){http_response_code(404);exit(count($matches)>1?'Este link antigo é ambíguo. Solicite o link atualizado do evento.':'Evento não encontrado.');}
    $event=$matches[0];$tenantSlug=(string)$event['tenant_slug'];
    if($_SERVER['REQUEST_METHOD']==='GET'){header('Location: '.app_url('event-bar.php?empresa='.rawurlencode($tenantSlug).'&evento='.rawurlencode($slug)),true,301);exit;}
}
if(!$event||!TenantFeatures::events((int)($event['tenant_id']??0))||!TenantFeatures::menu((int)($event['tenant_id']??0))){http_response_code(404);exit('Evento não encontrado.');}
if(!(int)($event['bar_enabled']??0)){http_response_code(404);exit('O cardápio do bar não está disponível para este evento.');}
$tenantId=(int)$event['tenant_id'];$eventId=(int)$event['id'];$unitId=(int)($event['bar_unit_id']??0);
if($unitId<1){http_response_code(503);exit('O atendimento do bar ainda não foi configurado.');}
$u=$pdo->prepare('SELECT id,code,name,address FROM operating_units WHERE id=? AND tenant_id=? AND active=1 LIMIT 1');$u->execute([$unitId,$tenantId]);$unit=$u->fetch();if(!$unit){http_response_code(503);exit('A unidade do bar está indisponível.');}

$brand=(new TenantBrandService())->get($tenantId);$configured=new ConfiguredOrderService();$error=null;
$cartKey='event_bar_cart_'.$tenantId.'_'.$eventId.'_'.$unitId;if(!isset($_SESSION[$cartKey])||!is_array($_SESSION[$cartKey]))$_SESSION[$cartKey]=[];$cart=&$_SESSION[$cartKey];
function eb_money(int$c):string{return'R$ '.number_format($c/100,2,',','.');}
function eb_qty(float$q):string{return abs($q-round($q))<.0005?(string)(int)round($q):rtrim(rtrim(number_format($q,3,',','.'),'0'),',');}
function eb_options(mixed$value):array{$out=[];$walk=function(mixed$v)use(&$out,&$walk):void{if(is_array($v)){foreach($v as$x)$walk($x);return;}$id=(int)$v;if($id>0)$out[]=$id;};$walk($value);$out=array_values(array_unique($out));sort($out);return$out;}
function eb_friendly(string$message):string{$m=trim($message);if($m===''||preg_match('/sql|sqlite|mysql|pdo|exception|database|stack|http\s*\d/i',$m))return'Não foi possível concluir agora. Tente novamente.';return preg_replace('/^(Financeiro|API|Servidor|Gateway)\s*:\s*/i','',$m)?:'Não foi possível concluir agora. Tente novamente.';}

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sua sessão expirou. Atualize a página.';
    else{
        $action=(string)($_POST['action']??'');
        try{
            if($action==='add'){
                $id=(int)($_POST['product_id']??0);$qty=max(1,min(99,(int)($_POST['qty']??1)));$optionIds=eb_options($_POST['option_ids']??[]);
                $availability=$pdo->prepare('SELECT p.id,p.track_stock,EXISTS(SELECT 1 FROM product_recipes r WHERE r.tenant_id=p.tenant_id AND r.product_id=p.id) has_recipe,COALESCE(ui.stock_qty,0) unit_stock FROM products p LEFT JOIN unit_inventory ui ON ui.tenant_id=p.tenant_id AND ui.unit_id=? AND ui.product_id=p.id WHERE p.id=? AND p.tenant_id=? AND p.active=1');$availability->execute([$unitId,$id,$tenantId]);$stock=$availability->fetch();if(!$stock)throw new RuntimeException('Produto indisponível.');if((int)$stock['track_stock']&&!(int)$stock['has_recipe']&&(float)$stock['unit_stock']<=0)throw new RuntimeException('Produto esgotado no bar.');
                $resolved=$configured->resolveLine($pdo,$tenantId,['product_id'=>$id,'qty'=>$qty,'option_ids'=>$optionIds],false);$key=hash('sha256',$id.':'.implode(',',$resolved['option_ids']));if(isset($cart[$key]))$cart[$key]['qty']=min(99,(float)$cart[$key]['qty']+$qty);else$cart[$key]=['product_id'=>$id,'qty'=>$qty,'option_ids'=>$resolved['option_ids']];
            }elseif($action==='remove')unset($cart[(string)($_POST['line_key']??'')]);
            elseif($action==='clear')$cart=[];
            elseif($action==='checkout'){
                $order=(new PublicMenuService())->create($tenantId,array_values($cart),(string)($_POST['name']??''),(string)($_POST['phone']??''),'',null,'bar',$eventId);$cart=[];header('Location: '.app_url('pedido.php?t='.rawurlencode((string)$order['public_token'])),true,303);exit;
            }
            if($action!=='checkout'){header('Location: '.app_url('event-bar.php?empresa='.rawurlencode($tenantSlug).'&evento='.rawurlencode($slug)),true,303);exit;}
        }catch(Throwable$e){$error=eb_friendly($e->getMessage());}
    }
}

$c=$pdo->prepare('SELECT id,name FROM categories WHERE tenant_id=? AND active=1 ORDER BY sort_order,name');$c->execute([$tenantId]);$categories=$c->fetchAll();$categoryNames=[];foreach($categories as$cat)$categoryNames[(int)$cat['id']]=(string)$cat['name'];
$p=$pdo->prepare('SELECT p.*,COALESCE(ui.stock_qty,0) unit_stock_qty,EXISTS(SELECT 1 FROM product_recipes r WHERE r.tenant_id=p.tenant_id AND r.product_id=p.id) has_recipe FROM products p LEFT JOIN unit_inventory ui ON ui.tenant_id=p.tenant_id AND ui.unit_id=? AND ui.product_id=p.id WHERE p.tenant_id=? AND p.active=1 ORDER BY p.category_id,p.name');$p->execute([$unitId,$tenantId]);$products=$p->fetchAll();$modifierCatalog=$configured->catalogModifiers($pdo,$tenantId,array_column($products,'id'));$groups=[];foreach($products as$prod){$groups[$categoryNames[(int)($prod['category_id']??0)]??'Outros'][]=$prod;}
$cartRows=[];$cartTotal=0;$cartCount=0;$invalid=[];foreach($cart as$key=>$line){try{$r=$configured->resolveLine($pdo,$tenantId,$line,false);$mods=[];foreach($r['modifiers']as$m)$mods[]=$m['group_name'].': '.$m['name'];$cartTotal+=(int)$r['total_cents'];$cartCount+=(int)ceil((float)$r['quantity']);$cartRows[]=['key'=>$key,'name'=>$r['name'],'qty'=>(float)$r['quantity'],'total'=>(int)$r['total_cents'],'mods'=>$mods];}catch(Throwable){$invalid[]=$key;}}foreach($invalid as$key)unset($cart[$key]);
$primary=(string)$brand['primary_color'];$background=(string)$brand['background_color'];$surface=(string)$brand['surface_color'];$text=(string)$brand['text_color'];$display=(string)$brand['display_name'];$logo=(string)$brand['logo_url'];$eventUrl=app_url('evento.php?empresa='.rawurlencode($tenantSlug).'&evento='.rawurlencode($slug));
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="<?= Security::e($primary) ?>"><title>Bar · <?= Security::e($event['name']) ?></title><style>
:root{--p:<?= Security::e($primary) ?>;--bg:<?= Security::e($background) ?>;--s:<?= Security::e($surface) ?>;--t:<?= Security::e($text) ?>;--muted:#77748a;--line:color-mix(in srgb,var(--t) 13%,transparent);--soft:color-mix(in srgb,var(--p) 9%,var(--s));--shadow:0 14px 38px rgba(30,20,60,.09)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}a{color:inherit;text-decoration:none}button,input{font:inherit}.shell{width:min(1120px,100%);margin:auto;padding:14px 14px 110px}.top{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:6px 0 14px}.identity{display:flex;align-items:center;gap:10px}.logo{width:46px;height:46px;border-radius:14px;object-fit:cover;background:var(--p);display:grid;place-items:center;color:#fff;font-weight:950}.identity strong,.identity small{display:block}.identity small{font-size:11px;color:var(--muted)}.back{border:1px solid var(--line);background:var(--s);padding:9px 11px;border-radius:10px;font-size:11px;font-weight:800}.hero{padding:24px;border-radius:20px;background:linear-gradient(135deg,color-mix(in srgb,var(--p) 20%,var(--s)),var(--s));border:1px solid var(--line);box-shadow:var(--shadow);margin-bottom:14px}.eyebrow{font-size:10px;font-weight:900;letter-spacing:.14em;color:var(--p)}h1{font-size:clamp(30px,6vw,52px);line-height:1;margin:6px 0 9px}.hero p{margin:0;color:var(--muted)}.meta{display:flex;gap:7px;flex-wrap:wrap;margin-top:14px}.pill{padding:7px 10px;border-radius:999px;background:var(--s);border:1px solid var(--line);font-size:10px;font-weight:800}.alert{padding:12px 14px;border-radius:12px;background:#fff0f1;color:#9b3f48;border:1px solid #efc8cc;margin:12px 0}.main{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:16px;align-items:start}.section{margin:18px 0 24px}.section h2{font-size:20px;margin:0 0 10px}.products{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.product{background:var(--s);border:1px solid var(--line);border-radius:15px;padding:13px;box-shadow:0 5px 17px rgba(30,20,60,.045)}.product-head{display:flex;justify-content:space-between;gap:10px}.product h3{margin:0 0 4px;font-size:15px}.product p{margin:0;color:var(--muted);font-size:10px;line-height:1.4}.price{font-weight:950;color:var(--p);white-space:nowrap}.add{display:flex;justify-content:flex-end;gap:6px;align-items:center;margin-top:10px}.add input[type=number]{width:52px;padding:7px;border:1px solid var(--line);border-radius:8px;background:var(--s);color:var(--t)}button{border:0;border-radius:9px;padding:8px 10px;background:var(--p);color:#fff;font-weight:850;cursor:pointer}button:disabled{opacity:.45}.mods{border-top:1px solid var(--line);margin-top:9px;padding-top:8px}.mods summary{font-size:10px;color:var(--p);font-weight:900;cursor:pointer}.mod-group{padding:8px 0}.mod-group strong{font-size:10px}.mod-option{display:flex;justify-content:space-between;gap:8px;padding:6px 0;font-size:10px}.cart{position:sticky;top:10px;background:var(--s);border:1px solid var(--line);border-radius:16px;padding:16px;box-shadow:var(--shadow)}.cart h2{margin:3px 0 10px;font-size:18px}.line{display:flex;justify-content:space-between;gap:10px;padding:9px 0;border-bottom:1px solid var(--line)}.line small{display:block;color:var(--muted);font-size:9px}.remove{background:transparent;color:var(--muted);border:1px solid var(--line);padding:5px 8px}.total{display:flex;justify-content:space-between;padding:13px 0;font-size:15px}.checkout{display:grid;gap:8px}.checkout label{display:grid;gap:4px;font-size:10px;font-weight:800}.checkout input{padding:10px;border:1px solid var(--line);border-radius:9px;background:var(--s);color:var(--t)}.checkout button{padding:12px}.info{padding:10px;border-radius:10px;background:var(--soft);font-size:10px;line-height:1.45}.empty{padding:22px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:12px}.mobile{display:none}@media(max-width:850px){.main{grid-template-columns:1fr}.products{grid-template-columns:1fr}.cart{position:static}.mobile{display:flex;position:fixed;left:10px;right:10px;bottom:max(10px,env(safe-area-inset-bottom));z-index:20;background:var(--p);color:#fff;justify-content:space-between;padding:12px 14px;border-radius:12px;font-weight:900;box-shadow:0 14px 30px rgba(30,20,60,.25)}}
</style></head><body><main class="shell"><header class="top"><div class="identity"><?php if($logo!==''):?><img class="logo" src="<?= Security::e($logo) ?>" alt=""><?php else:?><div class="logo"><?= Security::e(mb_strtoupper(mb_substr($display,0,1))) ?></div><?php endif;?><div><strong><?= Security::e($display) ?></strong><small>Bar do evento</small></div></div><a class="back" href="<?= Security::e($eventUrl) ?>">← Evento</a></header><section class="hero"><span class="eyebrow">PEDIDO NO EVENTO</span><h1><?= Security::e($event['name']) ?></h1><p>Peça pelo celular, pague online e retire no bar apresentando o QR do pedido.</p><div class="meta"><span class="pill"><?= Security::e($unit['name']) ?></span><?php if(!empty($event['venue'])):?><span class="pill"><?= Security::e($event['venue']) ?></span><?php endif;?><span class="pill">Retirada por QR</span></div></section><?php if($error):?><div class="alert"><?= Security::e($error) ?></div><?php endif;?><div class="main"><section><?php if(!$groups):?><div class="empty">O cardápio do bar ainda não possui produtos disponíveis.</div><?php else:?><?php foreach($groups as$group=>$rows):?><section class="section"><h2><?= Security::e($group) ?></h2><div class="products"><?php foreach($rows as$prod):$out=(int)$prod['track_stock']&&!(int)$prod['has_recipe']&&(float)$prod['unit_stock_qty']<=0;$mods=$modifierCatalog[(int)$prod['id']]??[];?><article class="product"><div class="product-head"><div><h3><?= Security::e($prod['name']) ?></h3><?php if(trim((string)($prod['description']??''))!==''):?><p><?= Security::e($prod['description']) ?></p><?php endif;?></div><span class="price"><?= eb_money((int)$prod['price_cents']) ?></span></div><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?= (int)$prod['id'] ?>"><?php if($mods):?><details class="mods"><summary>Personalizar</summary><?php foreach($mods as$groupMod):$max=max(1,(int)$groupMod['max_select']);$min=max((int)$groupMod['min_select'],(int)$groupMod['required']?1:0);?><div class="mod-group"><strong><?= Security::e($groupMod['name']) ?> · <?= $min ?>–<?= $max ?></strong><?php foreach($groupMod['options']as$opt):?><label class="mod-option"><span><input type="<?= $max===1?'radio':'checkbox' ?>" name="option_ids[<?= (int)$groupMod['id'] ?>]<?= $max===1?'':'[]' ?>" value="<?= (int)$opt['id'] ?>"> <?= Security::e($opt['name']) ?></span><b><?= (int)$opt['price_delta_cents']?Security::e(((int)$opt['price_delta_cents']>0?'+ ':'- ').eb_money(abs((int)$opt['price_delta_cents']))):'Incluído' ?></b></label><?php endforeach;?></div><?php endforeach;?></details><?php endif;?><div class="add"><input type="number" name="qty" min="1" max="99" value="1"<?= $out?' disabled':'' ?>><button<?= $out?' disabled':'' ?>><?= $out?'Esgotado':'Adicionar' ?></button></div></form></article><?php endforeach;?></div></section><?php endforeach;?><?php endif;?></section><aside class="cart" id="pedido"><span class="eyebrow">SEU PEDIDO</span><h2><?= $cartCount?$cartCount.' '.($cartCount===1?'item':'itens'):'Carrinho' ?></h2><?php if(!$cartRows):?><div class="empty">Adicione produtos para começar.</div><?php else:?><?php foreach($cartRows as$item):?><div class="line"><div><strong><?= Security::e(eb_qty($item['qty'])) ?>× <?= Security::e($item['name']) ?></strong><small><?= eb_money($item['total']) ?><?= $item['mods']?' · '.Security::e(implode(' · ',$item['mods'])):'' ?></small></div><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="line_key" value="<?= Security::e($item['key']) ?>"><button class="remove">×</button></form></div><?php endforeach;?><div class="total"><span>Total</span><strong><?= eb_money($cartTotal) ?></strong></div><form method="post" class="checkout"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="checkout"><div class="info">Depois do pagamento, acompanhe o pedido na mesma página. Quando estiver pronto, apresente o QR no bar.</div><label>Seu nome<input name="name" required autocomplete="name" placeholder="Como podemos te chamar?"></label><label>Telefone<input name="phone" required autocomplete="tel" inputmode="tel" placeholder="(22) 99999-9999"></label><button>Confirmar pedido</button></form><?php endif;?></aside></div></main><?php if($cartRows):?><a class="mobile" href="#pedido"><span>Ver pedido · <?= $cartCount ?> item(ns)</span><strong><?= eb_money($cartTotal) ?></strong></a><?php endif;?></body></html>